// Generated by scaffold-email
// SMTP adapter via nodemailer. Lazy-inits the transport from SMTP_HOST/PORT/USER/PASS
// env. send() is best-effort — a mail failure must NOT fail the triggering transaction
// (the in-app/DB state is the source of truth). When SMTP isn't configured it no-ops
// with a warning, so dev/test without a mail server still boots.
import { Injectable, Logger } from '@nestjs/common';
import * as nodemailer from 'nodemailer';

// An UNRESOLVED 1Password reference is not a credential. .env ships op:// pointers,
// substituted only when the process runs under `op run --env-file=.env -- …`. Without
// that, process.env holds the literal string — non-empty, so a truthiness guard reads it
// as configured, builds a client with a garbage secret and fails at the provider instead
// of falling back to the dev path. Strictly worse than unconfigured: nothing is sent AND
// the dev log that makes the flow testable is skipped.
const cred = (name: string): string | undefined => {
  const v = process.env[name];
  return v && !v.startsWith('op://') ? v : undefined;
};

@Injectable()
export class MailClient {
  private readonly logger = new Logger('MailClient');
  private transport: nodemailer.Transporter | null = null;
  private tried = false;

  private init(): nodemailer.Transporter | null {
    if (this.tried) return this.transport;
    this.tried = true;
    const host = cred('SMTP_HOST');
    if (!host || (cred('SMTP_USER') && !cred('SMTP_PASS'))) { this.logger.warn('SMTP not configured (host missing, or SMTP_PASS is still an op:// reference) — email disabled. Run under `op run --env-file=.env -- …` to send for real.'); return null; }
    try {
      this.transport = nodemailer.createTransport({
        host,
        port: Number(process.env.SMTP_PORT || 587),
        secure: process.env.SMTP_SECURE === 'true',
        auth: cred('SMTP_USER') ? { user: cred('SMTP_USER'), pass: cred('SMTP_PASS') } : undefined,
      });
      return this.transport;
    } catch (e) {
      this.logger.warn('SMTP init failed (email disabled): ' + (e as Error).message);
      return null;
    }
  }

  async send(to: string, subject: string, html: string, text?: string): Promise<boolean> {
    const t = this.init();
    if (!t) {
      // Parity with the SMS adapter: keep the flow testable without credentials.
      if (process.env.NODE_ENV !== 'production') this.logger.log(`[email:dev] to ${to}: ${subject}`);
      return false;
    }
    try {
      await t.sendMail({ from: process.env.MAIL_FROM || 'noreply@example.com', to, subject, html, text: text || html.replace(/<[^>]+>/g, '') });
      return true;
    } catch (e) {
      this.logger.warn('email send failed to ' + to + ': ' + (e as Error).message);
      return false;
    }
  }
}
